/*
* Safeguarding test for: feat(custom): reusable custom series
*
* A custom series can declare `itemPayload`; every `renderItem` invocation
* receives that same object through `params.itemPayload`, and rendering
* keeps working (with `itemPayload` undefined) when no payload is provided.
*/

import { EChartsType } from '../src/echarts';
import { createChart } from '../test/ut/core/utHelper';
import { CustomSeriesRenderItemAPI, CustomSeriesRenderItemParams } from '../src/chart/custom/CustomSeries';

describe('custom-series-item-payload', function () {

    let chart: EChartsType;
    afterEach(function () {
        chart && chart.dispose();
    });

    it('should pass itemPayload to every renderItem call', function () {
        chart = createChart();

        const itemPayload = { sharedThreshold: 10, unit: 'ms' };
        const received: CustomSeriesRenderItemParams['itemPayload'][] = [];

        chart.setOption({
            xAxis: { data: ['a', 'b', 'c'] },
            yAxis: {},
            series: [{
                type: 'custom',
                itemPayload: itemPayload,
                renderItem: function (params: CustomSeriesRenderItemParams, api: CustomSeriesRenderItemAPI) {
                    received.push(params.itemPayload);
                    return {
                        type: 'circle',
                        shape: {
                            cx: 0,
                            cy: 0,
                            r: api.value(1) as number
                        }
                    };
                },
                data: [1, 2, 3]
            }]
        });

        expect(received.length).toEqual(3);
        received.forEach(function (payload) {
            // The exact same object reference is shared across item rendering.
            expect(payload).toBe(itemPayload);
            expect((payload as typeof itemPayload).sharedThreshold).toEqual(10);
        });
